extern vec2 texelStep;      // texture coord offset equal to 1 screen pixel
extern vec4 outlineColor;   // RGBA
extern float threshold;     // alpha threshold
extern float radiusPx;      // outline radius in px (1=1px)
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
    float a0 = Texel(tex, tc).a;
    if (a0 <= threshold){
        vec2 s = texelStep;
        float a1 = Texel(tex, tc + vec2( s.x, 0.0)).a;
        float a2 = Texel(tex, tc + vec2(-s.x, 0.0)).a;
        float a3 = Texel(tex, tc + vec2(0.0,  s.y)).a;
        float a4 = Texel(tex, tc + vec2(0.0, -s.y)).a;
        float a5 = Texel(tex, tc + vec2( s.x,  s.y)).a;
        float a6 = Texel(tex, tc + vec2(-s.x, -s.y)).a;
        float a7 = Texel(tex, tc + vec2( s.x, -s.y)).a;
        float a8 = Texel(tex, tc + vec2(-s.x,  s.y)).a;
        float neighbor = max(max(max(a1,a2),max(a3,a4)), max(max(a5,a6),max(a7,a8)));
        if (radiusPx > 1.5){
            vec2 t = s * 2.0;
            float b1 = Texel(tex, tc + vec2( t.x, 0.0)).a;
            float b2 = Texel(tex, tc + vec2(-t.x, 0.0)).a;
            float b3 = Texel(tex, tc + vec2(0.0,  t.y)).a;
            float b4 = Texel(tex, tc + vec2(0.0, -t.y)).a;
            float b5 = Texel(tex, tc + vec2( t.x,  t.y)).a;
            float b6 = Texel(tex, tc + vec2(-t.x, -t.y)).a;
            float b7 = Texel(tex, tc + vec2( t.x, -t.y)).a;
            float b8 = Texel(tex, tc + vec2(-t.x,  t.y)).a;
            float neighbor2 = max(max(max(b1,b2),max(b3,b4)), max(max(b5,b6),max(b7,b8)));
            neighbor = max(neighbor, neighbor2);
        }
        if (neighbor > threshold){ return outlineColor; }
    }
    return vec4(0.0);
}

extern number time;
extern vec4 tintColor;

float colorDist(vec3 c1, vec3 c2) {
    return length(c1 - c2);
}

vec4 effect(vec4 color, Image texture, vec2 texture_coords, vec2 screen_coords) {
    // 1. Get original pixel to enforce strict alpha mask boundary
    vec4 originalColor = Texel(texture, texture_coords);
    if (originalColor.a < 0.01) {
        return vec4(0.0);
    }

    // 2. Sample texture at native resolution for perfectly sharp, crisp pixel art
    vec4 texColor = Texel(texture, texture_coords);
    vec3 rgb = texColor.rgb;
    vec3 finalRGB = rgb;

    // 3. Pixel-perfect original color groups from stage2.png & stage3.png
    // Group 1: Sky & Pale Highlights (Stage 3 and Stage 2 cave background wall)
    vec3 sky1 = vec3(178.0/255.0, 165.0/255.0, 146.0/255.0); // B2A592
    vec3 sky2 = vec3(207.0/255.0, 192.0/255.0, 171.0/255.0); // CFC0AB
    vec3 sky3 = vec3(228.0/255.0, 204.0/255.0, 183.0/255.0); // E4CCB7
    vec3 sky4 = vec3(194.0/255.0, 174.0/255.0, 152.0/255.0); // C2AE98
    vec3 sky5 = vec3(55.0/255.0, 46.0/255.0, 63.0/255.0);    // 372E3F (Stage 2 dominant back wall)
    vec3 sky6 = vec3(30.0/255.0, 28.0/255.0, 46.0/255.0);    // 1E1C2E (Stage 2 dark back wall)

    // Group 2: Midtone Clay & Ground
    vec3 mid1 = vec3(203.0/255.0, 158.0/255.0, 114.0/255.0); // CB9E72
    vec3 mid2 = vec3(175.0/255.0, 133.0/255.0, 102.0/255.0); // AF8566
    vec3 mid3 = vec3(179.0/255.0, 116.0/255.0, 92.0/255.0);  // B3745C
    vec3 mid4 = vec3(161.0/255.0, 134.0/255.0, 116.0/255.0); // A18674

    // Group 3: Dark Shadows & Deep Rocks
    vec3 dark1 = vec3(108.0/255.0, 72.0/255.0, 69.0/255.0);  // 6C4845
    vec3 dark2 = vec3(134.0/255.0, 122.0/255.0, 112.0/255.0); // 867A70
    vec3 dark3 = vec3(137.0/255.0, 101.0/255.0, 86.0/255.0);  // 896556

    // 4. Mapped Target Colors (Ultra-Flat Achromatic Silhouette Swap)
    // Snaps all ground, rocks, shadows, and extra colors to a single flat charcoal black (#141414).
    // Only the sky is a slightly lighter stone gray (#212121), creating a beautiful flat silhouette relief.
    // This completely obliterates all internal visual shapes, making the stage totally unrecognizable!
    vec3 targetSky = vec3(0.13, 0.13, 0.13);   // #212121 (Slightly lighter dark-gray sky)
    vec3 targetMid = vec3(0.08, 0.08, 0.08);   // #141414 (Flat dark charcoal ground)
    vec3 targetDark = vec3(0.08, 0.08, 0.08);  // #141414 (Flat dark charcoal shadows)

    float thres = 0.09; // Matching threshold

    // Apply dynamic color swapping
    if (colorDist(rgb, sky1) < thres || colorDist(rgb, sky2) < thres || colorDist(rgb, sky3) < thres || colorDist(rgb, sky4) < thres || colorDist(rgb, sky5) < thres || colorDist(rgb, sky6) < thres) {
        finalRGB = targetSky;
    } else if (colorDist(rgb, mid1) < thres || colorDist(rgb, mid2) < thres || colorDist(rgb, mid3) < thres || colorDist(rgb, mid4) < thres) {
        finalRGB = targetMid;
    } else if (colorDist(rgb, dark1) < thres || colorDist(rgb, dark2) < thres || colorDist(rgb, dark3) < thres) {
        finalRGB = targetDark;
    } else {
        // Fallback blend for extra colors - snapped flat to the dark ground color to eliminate all detail
        finalRGB = targetMid;
    }

    // 5. Force 100% pure achromatic gray (eliminate any possible color leak/tint)
    float gray = (finalRGB.r + finalRGB.g + finalRGB.b) / 3.0;
    finalRGB = vec3(gray);

    // Prevent compiler optimization of uniforms and guarantee strict boundaries using pure achromatic additions
    float dummy = (tintColor.r + tintColor.g + tintColor.b) * 0.000001 + time * 0.0000001;
    finalRGB += vec3(dummy);

    return vec4(finalRGB, originalColor.a * color.a);
}

extern number mixFactor;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    vec4 texcolor = Texel(tex, tc);
    vec3 finalRGB = mix(texcolor.rgb, vec3(1.0, 1.0, 1.0), mixFactor);
    return vec4(finalRGB, texcolor.a) * color;
}

extern number time;

vec4 effect(vec4 color, Image texture, vec2 texture_coords, vec2 screen_coords) {
    vec4 texColor = Texel(texture, texture_coords);
    vec2 uv = screen_coords / love_ScreenSize.xy;

    // Continuous low-frequency waves replace the old lattice/hash FBM.
    // Some low-precision fragment GPUs evaluated the hash in blocks, making
    // the cloud shade expose square cell boundaries. These inputs remain in
    // a small numeric range and contain no floor-based grid at all.
    const float TAU = 6.28318530718;
    float phase = time * (TAU / 100.0);
    float cloudField = 0.50;
    cloudField += 0.22 * sin(TAU * dot(uv, vec2(0.72, 0.31)) + phase);
    cloudField += 0.14 * sin(TAU * dot(uv, vec2(-0.38, 0.83)) - phase * 2.0 + 1.70);
    cloudField += 0.08 * sin(TAU * dot(uv, vec2(1.16, -0.54)) + phase * 3.0 + 0.60);
    float shadow = smoothstep(0.12, 0.88, cloudField);

    vec3 shadowTint = vec3(0.9, 0.9, 1.0);
    vec3 sunTint = vec3(1.05, 1.02, 0.98);

    vec3 finalRGB = texColor.rgb;
    // Apply the cloud over the full image. A separate screen-region cutoff,
    // however soft, can become a visible contour after driver quantization.
    float shadowAmt = shadow * 0.72;
    finalRGB = mix(finalRGB * sunTint, finalRGB * shadowTint * 0.7, shadowAmt);

    // Sub-pixel interleaved noise breaks up 8/10-bit gradient bands without
    // reading as grain at the virtual resolution or after integer scaling.
    float dither = fract(52.9829189
        * fract(dot(screen_coords, vec2(0.06711056, 0.00583715)))) - 0.5;
    finalRGB += vec3(dither * (1.0 / 255.0));

    return vec4(clamp(finalRGB, vec3(0.0), vec3(1.0)), texColor.a) * color;
}
